from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> [value, write_time]
    results = []

    def purge_expired(current_time):
        expired_keys = [k for k, (v, wt) in cache.items() if current_time - wt >= ttl]
        for k in expired_keys:
            del cache[k]

    for op in ops:
        kind = op[0]
        t = op[1]
        purge_expired(t)

        if kind == 'put':
            key = op[2]
            value = op[3]
            if key in cache:
                # not expired (already purged), update
                cache[key][0] = value
                cache[key][1] = t
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = [value, t]
                cache.move_to_end(key)
        elif kind == 'get':
            key = op[2]
            if key in cache:
                value, wt = cache[key]
                results.append(value)
                cache.move_to_end(key)
            else:
                results.append(-1)

    return results

